using Marketplace.Domain.Common; namespace Marketplace.Domain.Payments; public sealed class PaymentAttempt:AggregateRoot<long>{private PaymentAttempt(){}public long OrderId{get;private set;}public long CustomerId{get;private set;}public long AmountIRR{get;private set;}public string CurrencyCode{get;private set;}=null!;public decimal FxRateToIRR{get;private set;}public string Gateway{get;private set;}=null!;public string? GatewayTransactionId{get;private set;}public PaymentAttemptStatus Status{get;private set;}public DateTime CreatedAtUtc{get;private set;}public DateTime? CompletedAtUtc{get;private set;}public static PaymentAttempt Create(long id,long orderId,long customerId,long amount,string currency,decimal fx,string gateway){if(amount<=0||fx<=0||string.IsNullOrWhiteSpace(currency)||string.IsNullOrWhiteSpace(gateway))throw new DomainException("Invalid payment attempt.");return new(){Id=id,OrderId=orderId,CustomerId=customerId,AmountIRR=amount,CurrencyCode=currency.Trim().ToUpperInvariant(),FxRateToIRR=fx,Gateway=gateway.Trim(),Status=PaymentAttemptStatus.Pending,CreatedAtUtc=DateTime.UtcNow};}public void MarkRedirected(string? tx=null){RequireOpen();Status=PaymentAttemptStatus.Redirected;GatewayTransactionId=tx;}public void Succeed(string tx){if(Status is not(PaymentAttemptStatus.Pending or PaymentAttemptStatus.Redirected))throw new DomainException("Payment attempt is terminal.");Status=PaymentAttemptStatus.Succeeded;GatewayTransactionId=tx;CompletedAtUtc=DateTime.UtcNow;}public void Fail(){if(IsTerminal())throw new DomainException("Payment attempt is terminal.");Status=PaymentAttemptStatus.Failed;CompletedAtUtc=DateTime.UtcNow;}public void Cancel(){if(IsTerminal())throw new DomainException("Payment attempt is terminal.");Status=PaymentAttemptStatus.Cancelled;CompletedAtUtc=DateTime.UtcNow;}public void Expire(){if(IsTerminal())throw new DomainException("Payment attempt is terminal.");Status=PaymentAttemptStatus.Expired;CompletedAtUtc=DateTime.UtcNow;}private bool IsTerminal()=>Status is PaymentAttemptStatus.Succeeded or PaymentAttemptStatus.Failed or PaymentAttemptStatus.Cancelled or PaymentAttemptStatus.Expired;private void RequireOpen(){if(IsTerminal())throw new DomainException("Payment attempt is terminal.");}}
